class ConfigProbe{[STAThread]static void Main(){var sw=(SldWorks)Marshal.GetActiveObject("SldWorks.Application");sw.CommandInProgress=true;sw.DocumentVisible(true,1);var d=(ModelDoc2)sw.ActiveDoc;Console.WriteLine(d.GetTitle());Console.WriteLine(string.Join(",",(string[])d.GetConfigurationNames()));Console.WriteLine("Show="+d.ShowConfiguration2("Partition_DC"));Console.WriteLine("Active="+d.ConfigurationManager.ActiveConfiguration.Name);var a=(AssemblyDoc)d;foreach(Component2 c in (object[])a.GetComponents(false)){if(c.Name2.Contains("Pedestal")||c.Name2.Contains("Partition_adapter")){Console.WriteLine(c.Name2+" state="+c.GetSuppression()+" suppress="+c.SetSuppression2(0)+" now="+c.GetSuppression());}}sw.CommandInProgress=false;}}
